	}

	status := recorder.Status()
	if status == 0 {
		status = http.StatusOK
	}
	w.WriteHeader(status)
	if newBuf.Len() > 0 {
		_, err := w.Write(newBuf.Bytes())
		return err
	}
	return nil
}

