50	// TestInterceptHandleResponse covers the response replacement semantics of
51	// handle_response blocks against an original `respond "old" 500`:
52	//   - an explicit empty replacement body must produce the new status with an
53	//     empty body (Content-Length: 0) plus any headers set by the route
54	//   - a non-empty replacement body must replace both status and body, with
55	//     Content-Length recomputed and the original headers preserved
56	//   - a header-only route must keep the original status and body while
57	//     layering the new header on top
58	//   - a route that does nothing must replay the original response verbatim
59	//   - stale original Content-Length and Transfer-Encoding headers must not
60	//     truncate, duplicate or otherwise misframe the replacement body
61	func TestInterceptHandleResponse(t *testing.T) {
62		tester := caddytest.NewTester(t)
63		tester.InitServer(`{
64				skip_install_trust
65				admin localhost:2999
66				http_port     9080
67				https_port    9443
68				grace_period  1ns
69			}
70	
71			localhost:9080 {
72				respond /empty "old" 500
73				header /empty X-Case empty
74				respond /body "old" 500
75				header /body X-Case body
76				respond /hdronly "old" 500
77				header /hdronly X-Case hdronly
78				respond /noaction "old" 500
79				header /noaction X-Case noaction
80				respond /cl "this-is-a-very-long-old-body" 500
81				header /cl X-Case cl
82				respond /te "old" 500
83				header /te X-Case te
84				header /te Transfer-Encoding chunked
85	
86				intercept {
87					@empty {
88						status 500
89						header X-Case empty
90					}
91					handle_response @empty {
92						header X-Replaced yes
93						respond 200
94					}
95	
96					@body {
97						status 500
98						header X-Case body
99					}
100					handle_response @body {
101						respond "new" 202
102					}
103	
104					@hdronly {
105						status 500
106						header X-Case hdronly
107					}
108					handle_response @hdronly {
109						header X-Replaced yes
110					}
111	
112					@noaction {
113						status 500
114						header X-Case noaction
115					}
116					handle_response @noaction {
117					}
118	
119					@cl {
120						status 500
121						header X-Case cl
122					}
123					handle_response @cl {
124						respond "new" 202
125					}
126	
127					@te {
128						status 500
129						header X-Case te
130					}
131					handle_response @te {
132						respond "new" 202
133					}
134				}
135			}
136			`, "caddyfile")
137	
138		// explicit empty body: new status, the added header and an empty body
139		r, body := tester.AssertGetResponse("http://localhost:9080/empty", 200, "")
140		if r.Header.Get("X-Replaced") != "yes" {
141			t.Errorf("empty replacement: expected X-Replaced header %q, got %q", "yes", r.Header.Get("X-Replaced"))
142		}
143		if r.Header.Get("X-Case") != "empty" {
144			t.Errorf("empty replacement: expected original X-Case header to be preserved, got %q", r.Header.Get("X-Case"))
145		}
146		if r.ContentLength != 0 {
147			t.Errorf("empty replacement: expected Content-Length 0, got %d", r.ContentLength)
148		}
149		if len(r.TransferEncoding) != 0 {
150			t.Errorf("empty replacement: expected no Transfer-Encoding, got %v", r.TransferEncoding)
151		}
152		if body != "" {
153			t.Errorf("empty replacement: expected empty body, got %q", body)
154		}
155	
156		// non-empty replacement: new status and body, recomputed Content-Length
157		r, body = tester.AssertGetResponse("http://localhost:9080/body", 202, "new")
158		if body != "new" {
159			t.Errorf("replacement body: expected %q, got %q", "new", body)
160		}
161		if r.ContentLength != int64(len("new")) {
162			t.Errorf("replacement body: expected Content-Length %d, got %d", len("new"), r.ContentLength)
163		}
164		if r.Header.Get("X-Case") != "body" {
165			t.Errorf("replacement body: expected original X-Case header to be preserved, got %q", r.Header.Get("X-Case"))
166		}
167		if len(r.TransferEncoding) != 0 {
168			t.Errorf("replacement body: expected no Transfer-Encoding, got %v", r.TransferEncoding)
169		}
170	
171		// header-only route: original status and body survive, header is added
172		r, body = tester.AssertGetResponse("http://localhost:9080/hdronly", 500, "old")
173		if body != "old" {
174			t.Errorf("header-only: expected original body %q, got %q", "old", body)
175		}
176		if r.Header.Get("X-Replaced") != "yes" {
177			t.Errorf("header-only: expected X-Replaced header %q, got %q", "yes", r.Header.Get("X-Replaced"))
178		}
179		if r.Header.Get("X-Case") != "hdronly" {
180			t.Errorf("header-only: expected original X-Case header to be preserved, got %q", r.Header.Get("X-Case"))
181		}
182		if r.ContentLength != int64(len("old")) {
183			t.Errorf("header-only: expected Content-Length %d, got %d", len("old"), r.ContentLength)
184		}
185	
186		// no action at all: original response replayed verbatim
187		r, body = tester.AssertGetResponse("http://localhost:9080/noaction", 500, "old")
188		if body != "old" {
189			t.Errorf("no-action: expected original body %q, got %q", "old", body)
190		}
191		if r.Header.Get("X-Replaced") != "" {
192			t.Errorf("no-action: did not expect X-Replaced header, got %q", r.Header.Get("X-Replaced"))
193		}
194		if r.Header.Get("X-Case") != "noaction" {
195			t.Errorf("no-action: expected original X-Case header to be preserved, got %q", r.Header.Get("X-Case"))
196		}
197	
198		// stale, larger Content-Length must not truncate or stall the shorter
