205			t.Errorf("content-length: expected recomputed Content-Length %d, got %d", len("new"), r.ContentLength)
206		}
207		if len(r.TransferEncoding) != 0 {
208			t.Errorf("content-length: expected no Transfer-Encoding, got %v", r.TransferEncoding)
209		}
210	
211		// original Transfer-Encoding: chunked must not leak into or duplicate on
212		// the content-length-framed replacement
213		r, body = tester.AssertGetResponse("http://localhost:9080/te", 202, "new")
214		if body != "new" {
215			t.Errorf("transfer-encoding: expected replacement body %q, got %q", "new", body)
216		}
217		if r.ContentLength != int64(len("new")) {
218			t.Errorf("transfer-encoding: expected Content-Length %d, got %d", len("new"), r.ContentLength)
219		}
220		if len(r.TransferEncoding) != 0 {
221			t.Errorf("transfer-encoding: expected no Transfer-Encoding on the replacement, got %v", r.TransferEncoding)
222		}
223	}
